-- Données initiales du Complexe Scolaire Moderne Ibnou Issak (CSZI), saisies depuis la fiche papier 2025-2026 (version 2).
-- À exécuter APRÈS schema.sql, une seule fois. Vérifiez ensuite les noms, classes et réductions dans l'application.
-- Puis, connecté en super-admin, ajoutez le Fondateur via Plateforme > « + Fondateur ».
begin;
-- Une inscription par élève dans l'année en cours (créée automatiquement avec l'établissement).
select st.school_id, y.id, st.id, st.class_id, st.reduction, st.date_inscription
  from public.students st join public.school_years y on y.school_id = st.school_id and y.is_current
 where st.school_id = '5c2a0000-0000-4000-8000-000000000001'
   and not exists (select 1 from public.enrollments e where e.student_id = st.id and e.year_id = y.id);
commit;
